G=load()
from collections import deque
def f(g):
    g=[row[:] for row in g]; h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(v for r in g for v in r)
    # dominant = background
    bg=max(cnt,key=lambda v:cnt[v]); sh=next(v for v in cnt if v!=bg) if len(cnt)>1 else None
    out=[r[:] for r in g]
    seen=[[False]*w for _ in range(h)]; dq=deque()
    for r in range(h):
        for c in [0,w-1]:
            if g[r][c]==bg and not seen[r][c]: seen[r][c]=True; dq.append((r,c))
    for c in range(w):
        for r in [0,h-1]:
            if g[r][c]==bg and not seen[r][c]: seen[r][c]=True; dq.append((r,c))
    while dq:
        r,c=dq.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and g[nr][nc]==bg and not seen[nr][nc]:
                seen[nr][nc]=True; dq.append((nr,nc))
    for r in range(h):
        for c in range(w):
            if g[r][c]==bg and not seen[r][c]: out[r][c]=4
    return out
