import numpy as np, json
def enc_comps(g,bg,diag=False):
    g=g.copy(); h,w=g.shape; seen=np.zeros_like(g); dq=[]
    for r in range(h):
        for c in (0,w-1):
            if g[r,c]==bg and not seen[r,c]: seen[r,c]=True; dq.append((r,c))
    for c in range(w):
        for r in (0,h-1):
            if g[r,c]==bg and not seen[r,c]: seen[r,c]=True; dq.append((r,c))
    steps=[(1,0),(-1,0)]+([(1,1),(-1,-1)]*(diag//1)) if diag else [(1,0),(-1,0),(0,1),(0,-1)]
    while dq:
        x,y=dq.pop()
        for dr,dc in steps:
            nr,nc=x+dr,y+dc
            if 0<=nr<h and 0<=nc<w and g[nr,nc]==bg and not seen[nr,nc]:
                seen[nr,nc]=True; dq.append((nr,nc))
    return (np.argwhere(g==bg)&seen)!=seen
